'use strict';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={gentle:'やさしい',normal:'ふつう',hard:'ハード'}, groups={main:'本編',free:'フリー／第三幕・紅角の丘',quest:'町の依頼',restoration:'復興本編',restRequest:'復興依頼',legend:'伝説級'}, shops={aquamist:'アクアミスト',grey:'灰色の街',stone:'石の村',rainbow:'虹の城下町'},slots={blade:'刻印',cloth:'衣',charm:'飾り'};
let D=null,selectedStage='gran',selectedSpirit='gran',selectedMini='voyage',compared=[], notes={};
try{notes=JSON.parse(localStorage.getItem('cr-guide-checklist-v1')||'{}');if(!notes||typeof notes!=='object'||Array.isArray(notes))notes={};}catch{notes={};}
const post=()=>$('#showPostgame').checked;
const itemName=id=>D.gear.find(g=>g.id===id)?.name||D.items.find(g=>g.id===id)?.name||D.materials[id]?.name||id;
const visibleStage=s=>post()||!s.postgame;
const activeTier=s=>s.hardOnly?'hard':$('#stageDifficulty').value;
const empty=text=>`<p class="empty-state">${esc(text)}</p>`;
const loot=bag=>`<div class="loot-chips">${Object.entries(bag||{}).map(([id,n])=>`<span class="loot-chip"><img src="media/${esc(id)}.webp" alt=""><button data-loot="${esc(id)}">${esc(itemName(id))} ×${n}</button></span>`).join('')||'<span class="small-note">なし</span>'}</div>`;
function mission(m,s){return {turns:`${m.n}ターン以内にクリア`,hp:`アリアのHP${m.n}%以上`,teamHP:`二人のHPをそれぞれ${m.n}%以上残す`,back:`背後から${m.n}回攻撃`,crit:`会心の一撃を${m.n}回`,summonKill:`召喚した精霊で${m.n}体撃破`,enchantKill:`${s?.postgame?'宿した心剣・四響の剣':'精霊を宿した心剣'}で${m.n}体撃破`,flashMulti:'透明の一閃で2体同時に攻撃',noSpirit:'精霊の力を借りない',noItem:'道具を使わない',noDown:'召喚した精霊を倒させない',rainbow:`クリア時に味方の床${m.n}%以上`,dullMax:`くすみの最大値を${m.n}%未満に保つ`,bossLast:'核を最後に倒す',spiritUse:`${D.spirits[m.spirit]?.name||''}の力を${m.n}回使う`,skillUse:`${m.spirit?D.spirits[m.spirit]?.name+'から':''}覚えた技を${m.n}回使う`,purify:`浄化を${m.n}回使う`,guardianVoice:'守り手の理性を3段階取り戻す'}[m.type]||m.type;}
function hint(m){return {turns:'移動だけの手番を減らし、複数の敵を範囲技でまとめて処理。序盤に必要な回数条件を稼ぎ、最後の敵を残して不足を確認。',hp:'終了時の四捨五入したHP割合で判定。最後の敵へ決着をつける前に回復。道具禁止の条件があれば回復スキルを使う。',teamHP:'アリアとクロムの両方が指定割合以上必要。片方だけの全回復では達成できないので、残りHPの低い方を先に立て直す。',back:'敵の正面マーカーと背後表示を見て背中へ回る。エンチャントの2回通常攻撃なら回数を稼ぎやすい。必中でも背後位置で命中すれば加算。',crit:'背後からの通常攻撃で会心率を上げ、会心装備も活用。結果には乱数があるため、残り敵数に余裕を持たせる。',summonKill:'登場効果だけに頼らず、アリアで削って召喚精霊の攻撃でとどめ。精霊が倒れる前に回復・守りを使う。',enchantKill:'対象の精霊を宿した状態のアリアの攻撃でとどめ。通常攻撃2回を活用。復興編ではクロムの四響の剣でも加算。',flashMulti:'同じ一閃の範囲に2体を収める。単体への2回使用では条件を満たさない。敵の接近を利用して位置を合わせる。',noSpirit:'召喚・エンチャントを使う前に条件を確認。通常攻撃、透明の一閃、道具と地形を利用する。',noItem:'茶・粉・香などの道具は使わず、覚えた回復技や精霊の登場効果、床の加護で立て直す。',noDown:'召喚した精霊の戦闘不能が失敗条件。召喚せずクリアする方法も可能。他のミッションに召喚撃破があれば安全な場所へ呼ぶ。',rainbow:'終了時の味方床割合を満たす。敵を倒す前に広範囲の塗り、歩行の装備、浄化で床を増やす。クリア後の演出による全塗りは判定に使えない。',dullMax:'判定は途中の最大割合。「指定値ちょうど」は失敗なので余裕を取る。ボスの予告床を虹に戻し、早い段階から塗る。',bossLast:'核以外の敵を先に倒す。核の範囲攻撃へほかの敵を巻き込むときも、核の残りHPに注意。増援も残さない。',spiritUse:'召喚またはエンチャントの使用回数を指定精霊で稼ぐ。ほかの精霊の使用や、習得済み技だけでは代わりにならない。',skillUse:'アリアがその精霊から習得した技を指定回数使う。召喚やエンチャントだけでは加算されない。技の共鳴を確保しておく。',purify:'アリアとクロムの「浄化」を合計で指定回数。灯を点け終えても回数が足りなければ床へ使う。共鳴は1回2。',guardianVoice:'HP2/3・1/3で行動が変化。1撃で全段階を飛ばせないので、予告に対応しながら会話を進める。'}[m.type]||'戦場で進行を確認してください。';}
function gateText(s){if(s.requiredCompanions?.length)return`${D.chapters.find(c=>c.key===s.gate)?.act||'章'}解放 ＋ ${s.requiredCompanions.map(id=>D.spirits[id].name).join('・')}の加入会話を完了`;if(s.hardOnly)return'クロム撃破・エピローグ完了後、復興の旅を開始';if(s.bondNeed)return`${D.chapters.find(c=>c.key===s.gate)?.act||s.gate}解放 + ${D.spirits[s.bondNeed.spirit].name}の絆${s.bondNeed.n}`;if(s.gate==='fury')return'第三幕解放、紅角の丘の物語から進む';if(s.gate==='mari_return')return'復興第3話クリア後、第4話の本編';if(s.postgame&&typeof s.gate==='number')return s.gate===0?'復興の旅を開始':`復興本編${s.gate+1}話クリア`;if(s.gate==='done')return'クロム撃破・エピローグ完了';if(s.gate)return`${D.chapters.find(c=>c.key===s.gate)?.act||s.gate}を解放`;if(s.id.startsWith('restore'))return`復興第${s.id.slice(7)}話の本編`;const node=D.worldNodes.find(n=>n.id===s.id||n.board===s.id);return D.chapters.find(c=>c.key===(node?.chapter||node?.need))?.act?`${D.chapters.find(c=>c.key===(node.chapter||node.need)).act}解放`:'物語・マップの進行に合わせて解放';}
function stageMatches(){const q=$('#stageSearch').value.trim(),g=$('#stageGroup').value,t=$('#stageType').value;return D.stages.filter(s=>visibleStage(s)&&(g==='all'||s.group===g)&&(t==='all'||s.boss===(t==='boss'))&&(!q||[s.title,s.id,s.act,s.description,...s.missions.map(m=>mission(m,s)),itemName(s.tiers.hard.rewards.sEquipment||'')].join(' ').includes(q))).sort((a,b)=>{const order=['main','free','quest','restoration','restRequest','legend'];return order.indexOf(a.group)-order.indexOf(b.group)||(a.tiers.normal||a.tiers.hard).level-(b.tiers.normal||b.tiers.hard).level;});}
function renderStages(){const list=stageMatches();$('#stageCount').textContent=`${list.length}件表示 / 全${D.stages.length}ステージ · ${post()?'復興編を含む':'復興編は非表示'} · 難易度を変えると適正Lvと報酬が変わります`;if(!list.some(s=>s.id===selectedStage))selectedStage=list[0]?.id;$('#stageList').innerHTML=list.map(s=>`<button data-stage="${s.id}" aria-pressed="${s.id===selectedStage}"><small>${groups[s.group]} · ${s.boss?'ボス戦':'通常戦'}${s.hardOnly?' · ハード専用':''}</small><b>${esc(s.title)}</b><span>${s.tiers[activeTier(s)].level}<small>Lv</small></span></button>`).join('')||empty('条件に合うステージがありません。名前や分類を変えてください。');renderStage();}
const patternText={tide:['味方を狙う横一列','隣接する横列も危険','二本の潮線が続く'],clock:['ボス周囲3マスの交互目盛り','4マス範囲の交互目盛り','5マス範囲の3周期目盛り'],vines:['狙われた味方の周り1マスの輪','周り2マスの輪','周り3マスの輪'],shell:['ボスの周り1マスの環','周り2マスの環','周り2・3マスの環'],prism:['斜め一方向の光','二方向の斜め線','交差する斜めの光'],night:['盤面の外周','外周と味方の横列','外周と味方の横列'],lighthouse:['味方を狙う縦一列','隣の縦列も危険','二本の灯列が続く'],carp:['ボスと味方の二本の横列','二本の水路','二本の横列＋味方の縦列'],orchard:['味方の周り2マスの輪','周り2・4マスの輪','周り2・5マスの輪'],crane:['ボス中心の十字','ボス中心の十字','十字＋両方向の斜め線'],hearth:['狙われた味方の周り1マス以内','周り2マス以内','周り3マス以内'],lantern:['味方の方向へ細い扇形','4マス範囲へ広い扇形','5マス範囲へさらに広い扇形'],crown:['ボスから左右1列の縦線','左右2列の縦線','左右3列＋味方の横列'],starglass:['3マス範囲の星目盛り','4マス範囲の星目盛り','5マス範囲の星目盛り'],charge:['味方の方向へ一直線','並ぶ二本の突進線','突進線と味方の列が交差'],cocoon:['ボスの周り2マスの輪','周り3マスの輪','周り4マスの輪＋味方の周り1マス']};
function phases(p){return `<p>${esc(p.counter)} 予告は次の敵の手番に発動。予告された床を虹に戻すと、侵食・傷・追加効果を防げます。HP2/3・1/3では侵食が広がるため、直前に味方の床を確保。</p><div class="phase-grid">${p.phases.map((v,i)=>`<article><span>${['Ⅰ','Ⅱ','Ⅲ'][i]}</span><h5>${esc(v.name)}</h5><p>${['HP2/3より上','HP1/3より上〜2/3','HP1/3以下'][i]}<br>${esc(v.skill)}</p><p class="phase-pattern">${esc(patternText[p.pattern]?.[i]||p.counter)}</p><p>移動${v.mov} / 射程1〜${v.rng[1]} / 特殊威力${v.power}倍${v.armor?` / 殻${v.armor}枚`:''}</p><details><summary>この段階の会話</summary>${v.lines.map(([who,line])=>`<p class="phase-line">${esc(who)}「${esc(line)}」</p>`).join('')}</details></article>`).join('')}</div><p class="small-note">穢れのHPを削ると理性が戻ります。各段階の境界でダメージが止まるため、強い一撃でも3段階を飛ばせません。特殊威力は攻撃力に掛かる値です。</p>`;}
function renderStage(){const s=D.stages.find(s=>s.id===selectedStage);if(!s){$('#stageDetail').innerHTML=empty('ステージを選んで詳細を確認してください。');return;}const key=activeTier(s),d=s.tiers[key],reward=d.rewards,p=D.guardians.find(p=>p.id===s.guardian),skillOptions=s.companionsByStory?'加入済みの精霊。森を先に通ればアイビーも使用可':s.spirits?.filter(id=>true).map(id=>D.spirits[id]?.name).join('・');const done=notes[s.id+'@'+key]===true;
$('#stageDetail').innerHTML=`<span class="badge">${esc(s.act)}</span><span class="badge teal">${names[key]}${s.hardOnly?'専用':''} · ${s.boss?'ボス戦':'通常戦'}</span><h3>${esc(s.title)}</h3><p>${esc(s.description)}</p><div class="stage-stats"><span>適正レベル<b>${d.level}</b></span><span>敵の初期数<b>${d.enemies.reduce((n,e)=>n+(e.n||1),0)}</b></span><span>開始共鳴<b>${s.spStart??'—'}</b></span><span>復興の灯<b>${s.beacons}</b></span></div><p class="small-note">解放：${esc(gateText(s))}<br>盤面 ${s.board.cols}×${s.board.rows}${skillOptions?` / ${s.companionsByStory?'編成':'基本精霊'}：${esc(skillOptions)}`:''}。追加加入の精霊は加入記録に従って使えます。</p><h4>敵の初期編成</h4><div class="table-wrap"><table><thead><tr><th>敵</th><th>Lv</th><th>数</th><th>注意点</th></tr></thead><tbody>${d.enemies.map(e=>`<tr><td>${esc(e.kind==='boss'?s.bossName||'穢れの核':D.kindNames[e.kind]||e.kind)}</td><td>${e.lv}</td><td>${e.n||1}</td><td>${esc({shade:'近接してくる影。背後回数や撃破条件に利用。',thorn:'射程2〜3。接近や移動封じで対処。',lead:`鉛の殻${e.armor||2}枚。守り無視の技が有効。`,membrane:e.phase?'戦闘の第2段階で出現。白い膜だけを切る。':'射程1〜2。複数の膜を範囲技で処理。',chrome:'直接HPを削る勝負ではない。下の攻略を確認。',boss:s.bossShield?'全ての復興の灯を点けるまで防壁が保護。':s.guardian?'HP2/3・1/3で予告と会話が変化。':'増援と残りの影に注意。'}[e.kind]||'')}</td></tr>`).join('')}</tbody></table></div><p class="small-note">やさしい：敵Lv−1・HP×0.85。ハード：敵Lv+2・HP×1.15・攻撃×1.08。推薦Lvは基準−1／±0／+3。表は選んだ難易度の値です。増援の数は初期編成に含めていません。</p><h4>S評価の条件と手順</h4>${s.missions.length?`<ol class="mission-list">${s.missions.map(m=>`<li><b>${esc(mission(m,s))}</b><p>${esc(hint(m))}</p></li>`).join('')}</ol>`:`<p>${s.par||d.enemies.reduce((n,e)=>n+(e.n||1),0)+3}ターン以内でS評価。</p>`}${s.missionGuide?`<p class="guide-note">${esc(s.missionGuide)}</p>`:''}${s.beacons?`<p><b>勝利条件：</b>敵全滅と${s.beacons}個の灯の点灯。浄化は共鳴2・射程2。${s.bossShield?'まず全ての灯を点けて核の防壁を開く。':''}アリアかクロムが倒れると敗北です。</p>`:''}${p?`<h4>ボスの3段階と予告</h4>${phases(p)}`:s.id==='chrome'?`<details class="guide-details"><summary>クロム戦の特殊な進め方を読む（終章の内容）</summary><div class="details-content"><p>最初はクロムへ心剣を2回当て、戦闘中の会話を進めます。ノアールが小さな夜空を取り戻すと、アリアの色が虹として現れ、白い膜を切り分ける戦いへ。クロム本人の黒を消す戦いではありません。6枚の膜を倒し、「小さな夜空」で床を整えましょう。</p></div></details>`:s.boss?'<p>核の周りの影を整理し、背後や守り無視で削る。増援があれば回数条件へ利用。核を最後に倒す条件があるときは、範囲技の巻き込みに注意してください。</p>':''}<h4>選んだ難易度の報酬</h4><div class="reward-columns"><div><h5>初クリアの道具</h5>${loot(reward.firstItems)}</div><div><h5>初S ${reward.unique?'· ユニーク装備':key==='hard'?'· 通常装備':'· 道具'}</h5>${loot(reward.sEquipment?{[reward.sEquipment]:1}:reward.sItems)}${loot({m_core:1})}</div><div><h5>毎回のクリア素材</h5>${loot(d.materials)}</div><div><h5>各ミッション初達成</h5>${loot({m_dust:1,[Object.keys(d.materials).find(id=>id!=='m_dust')]:1})}<p class="small-note">上記を達成した条件ごとに1回。初Sの核も難易度ごとに1回。</p></div></div><p class="small-note">しずく倍率：${d.rewardScale}倍 × 評価倍率。${s.firstGold?`クリア基礎額 ${s.firstGold}しずく。`:''}所持済み装備の初S報酬はゲームの換金処理に従います。</p><div class="stage-finish"><button class="${done?'outline':'play'}" id="finishStage" aria-pressed="${done}">${done?'攻略済み ✓':'この難易度を攻略済みにする'}</button><span>攻略帳専用メモ · ゲームの記録は変更しません</span></div>${storyForStage(s)?`<p><a class="text-link" href="story.html#${storyForStage(s)}">この戦場の物語を読む →</a></p>`:''}`;
$('#finishStage').onclick=()=>{const id=s.id+'@'+key;notes[id]=!notes[id];if(!notes[id])delete notes[id];try{localStorage.setItem('cr-guide-checklist-v1',JSON.stringify(notes));}catch{}renderStage();renderChecklist();};}
function storyForStage(s){if(s.gate==='fury'||s.id==='f_fruit')return'fury';if(s.gate==='mari_return')return'restore4';if(typeof s.gate==='string'&&D.chapters.some(c=>c.key===s.gate))return s.gate;return{cove:'prologue',gran:'act1',ivy:'act3',spinel:'act4',king:'act5',chrome:'finale'}[s.id]||(s.id.startsWith('restore')?s.id:null);}
function openStage(id){const s=D.stages.find(s=>s.id===id);if(!s)return;if(s.postgame)$('#showPostgame').checked=true;$('#stageSearch').value='';$('#stageGroup').value='all';$('#stageType').value='all';selectedStage=id;renderStages();renderSpirits();renderGear();$('#stageDetail').scrollIntoView({behavior:motion(),block:'start'});}
const motion=()=>matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth';
const bios={gran:['潮の癒しと足場','第一幕のグラン解放後に加入。マリーの帰りを鐘楼で待ち続けた鯨の精霊。'],ivy:['移動封じと回復','第三幕のアイビー解放後に加入。比較の言葉に縛られた森の精霊。木陰は休む場所で、閉じ込める檻ではありません。'],spinel:['守りと鉛への対処','第四幕のスピネル解放後に加入。鉛の殻に閉じこもった精霊が、傷の光で仲間を守ります。'],vard:['失ったHPを攻撃力へ','第三幕解放後、紅角の丘の通常戦→ボス戦→加入会話で仲間になります。妻子を失った怒りを抱えた紅い竜。ヴァルド戦クリア後、その場でグランと意気投合。過去にマリーと出会っています。'],mari:['追い風と世界の知識','クロム撃破後の復興第4話で救出して加入。多くの世界と人を知り、復興本編の中心で帰る道を導きます。']};
function renderSpirits(){const currentPlan=$('#planSpirit').value;$('#planSpirit').innerHTML=Object.entries(D.spirits).filter(([id])=>id!=='king').map(([id,s])=>`<option value="${id}">${s.name}</option>`).join('');if(currentPlan&&[...$('#planSpirit').options].some(o=>o.value===currentPlan))$('#planSpirit').value=currentPlan;$('#spiritPicker').innerHTML=Object.keys(D.spirits).filter(id=>id!=='king').map(id=>`<button data-spirit="${id}" aria-pressed="${id===selectedSpirit}"><img src="media/${id}.png" alt="">${D.spirits[id].name}</button>`).join('');const id=selectedSpirit,p=D.spiritActions[id];$('#spiritProfile').innerHTML=`<img src="media/${id}.png" alt="精霊${D.spirits[id].name}"><div><p class="eyebrow">${esc(bios[id][0])}</p><h3>${D.spirits[id].name}</h3><p class="join-note">${esc(bios[id][1])}</p><div class="spirit-actions"><div><b>エンチャント · 共鳴3</b><p>${esc(p.enchant.name)}：${esc(p.enchant.desc)}。通常攻撃2回。</p></div><div><b>召喚 · 共鳴6</b><p>${esc(p.summon.name)}：${esc(p.summon.desc)}。基本3ターン同行。</p></div></div></div>`;renderSkills();}
function renderSkills(){const lv=+$('#skillLevel').value,r=$('#skillRoute').value,q=$('#skillSearch').value.trim();const list=D.skills.filter(s=>s.spirit===selectedSpirit&&(r==='all'||s.route===r)&&(!q||(s.name+s.desc).includes(q))).sort((a,b)=>a.route.localeCompare(b.route)||a.at-b.at);$('#skillCards').innerHTML=list.map(s=>{const v=s.levels[lv],vals=[v.power?`威力${v.power}倍`:null,v.heal?`回復${Math.round(v.heal*100)}%`:null,v.guard?`守り${v.guard}ターン`:null,v.wind?`追い風${v.wind}ターン`:null,v.root?`縛り${v.root}ターン`:null,v.drain?`吸収${Math.round(v.drain*100)}%`:null,v.pierce?'守り・鉛無視':null,`射程${v.range}`,v.radius?`対象範囲${v.radius}`:null,v.paint?`塗り範囲${v.paint}`:null].filter(Boolean);return `<article class="skill-card" id="skill-${s.id}" style="--skill-color:${D.spirits[s.spirit].color}"><span class="badge">${s.route==='enchant'?'エンチャント':'召喚'} · 熟練${s.at}</span><span class="badge teal">${s.type} · 共鳴${s.cost}</span><h3>${esc(v.name)}</h3><p>${esc(v.desc)}</p><div class="skill-values">${vals.map(t=>`<span>${esc(t)}</span>`).join('')}</div>${lv<3?`<h4>次の強化 +${lv+1} の素材</h4>${loot(s.recipes[lv])}`:'<p class="small-note">最大強化。これ以上の素材は不要です。</p>'}</article>`;}).join('')||empty('該当する技がありません。');}
function renderPlanner(){const from=+$('#planFrom').value,to=+$('#planTo').value,count=Number($('#planCount').value),s=D.skills.find(s=>s.spirit===$('#planSpirit').value);if(to<=from||!Number.isInteger(count)||count<1||count>6){$('#planResult').innerHTML=empty('目標は現在より上の段階、技の数は1〜6で入力してください。');return;}const cost={};for(let lv=from;lv<to;lv++)for(const[id,n]of Object.entries(s.recipes[lv]))cost[id]=(cost[id]||0)+n*count;$('#planResult').innerHTML=loot(cost)+`<p class="small-note">${D.spirits[s.spirit].name}の${count}技を${from?'+'+from:'未強化'} → +${to}へ。段階ごとに強化します。</p>`;}
function rarity(g){return g.legendary?'legendary':g.unique?'unique':g.slot?'ordinary':g.material?'material':'item';}
function renderGear(){const q=$('#gearSearch').value.trim(),k=$('#gearKind').value,slot=$('#gearSlot').value;const all=[...D.gear,...D.items,...Object.entries(D.materials).map(([id,v])=>({id,...v,material:true}))];const list=all.filter(g=>(post()||!g.legendary)&&(k==='all'||rarity(g)===k)&&(slot==='all'||g.slot===slot)&&(!q||[g.name,g.desc,g.source,g.lore].join(' ').includes(q)));$('#gearCount').textContent=`${list.length}件表示 / 装備43・道具5・素材6。装備は2つ選んで比較できます。`;$('#gearCards').innerHTML=list.map(g=>`<article class="gear-card ${rarity(g)}" id="gear-${g.id}"><div><img src="media/${g.id}.webp" alt="${esc(g.name)}" loading="lazy"><div><small>${g.slot?slots[g.slot]+' · ':''}${{ordinary:'通常装備',unique:'ユニーク',legendary:'伝説装備',item:'道具',material:'強化素材'}[rarity(g)]}</small><h3>${esc(g.name)}</h3></div></div><p class="gear-fx">${esc(g.desc)}</p>${g.lore?`<p class="lore">${esc(g.lore)}</p>`:''}${g.price?`<p>店頭 ${g.price}しずく</p>`:''}<div class="gear-sources">${(g.sources||[]).filter(id=>visibleStage(D.stages.find(s=>s.id===id))).map(id=>`<button class="text-link" data-open-stage="${id}">${esc(D.stages.find(s=>s.id===id).title)} · ハードS</button>`).join('')}${(g.shops||Object.entries(D.materialShops).filter(([,v])=>v.includes(g.id)).map(([id])=>id)).map(id=>`<span class="badge">${shops[id]||id}の店</span>`).join('')}</div>${g.material?`<p>入手：${esc(g.source)}${g.id==='m_gold'?'。ヴァルドの強化にも使用。':g.id==='m_violet'?'。マリーの強化にも使用。':''}</p>`:''}${g.unique&&!g.sources?.length?'<p class="small-note">現在の報酬に入手先なし。過去の仕様で獲得した装備の資料として収録。</p>':g.sources?.length&&!g.sources.some(id=>visibleStage(D.stages.find(s=>s.id===id)))?'<p class="small-note">入手先はクリア後。復興編の表示で確認できます。</p>':''}${g.slot?`<button class="compare-toggle" data-compare="${g.id}" aria-pressed="${compared.includes(g.id)}">${compared.includes(g.id)?'比較から外す':'装備を比較'}</button>`:''}</article>`).join('')||empty('該当する装備・素材がありません。');renderCompare();}
function renderCompare(){const box=$('#compareBox');box.hidden=!compared.length;if(!compared.length)return;const gs=compared.map(id=>D.gear.find(g=>g.id===id)),attrs=[...new Set(gs.flatMap(g=>Object.keys(g.fx)))],labels={atk:'攻撃',def:'守り',hp:'HP',crit:'会心(%)',mov:'移動',jump:'段差',rng:'射程',spMax:'共鳴上限',spTurn:'毎ターン共鳴',back:'背後補正(%)',enchantTurns:'宿し延長',summonTurns:'召喚延長',regen:'毎ターン回復(%)',killHeal:'撃破回復(%)',flashCost:'一閃コスト減',evade:'回避(%)',paintStep:'周囲の歩行塗り',splash:'攻撃周囲の塗り',dullGuard:'くすみ耐性',killSp:'撃破共鳴',spStart:'開始共鳴'};box.innerHTML=`<h3>装備を並べて比較</h3><p>${gs.length===1?'もう1つ選んで比較。':gs[0].slot===gs[1].slot?'同じ部位の選択肢として比較。':'異なる部位です。装備する場所が違います。'}</p><div class="table-wrap"><table><thead><tr><th>効果</th>${gs.map(g=>`<th>${esc(g.name)}<br><small>${slots[g.slot]}</small></th>`).join('')}</tr></thead><tbody>${attrs.map(a=>`<tr><td>${labels[a]||a}</td>${gs.map(g=>`<td>${g.fx[a]??'—'}</td>`).join('')}</tr>`).join('')}</tbody></table></div><button class="outline" id="clearCompare">比較をクリア</button>`;$('#clearCompare').onclick=()=>{compared=[];renderGear();};}
const miniTips={voyage:['次の海を先読みし、移動できる隣のレーンから岩礁を避ける。星の連続取得で12+2×連続数（最大8）の得点。','疾走は風力2で2マス進み、星の得点が2倍。同じレーンの次の2マスを見て安全なときに使う。岩礁に当たると船体−2。','護りは風力1で岩礁の傷を防ぐ。寄港では船体+2／風力+2／宝+28から状況に合うものを選ぶ。','Sは round(宝の輝き÷目標×100) − 岩礁に当たった回数×3 ≥95。無傷で目標付近へ届く航路を選ぶ。'],lantern:['押した灯りと上下左右の灯りが反転します。斜めの灯りは変わりません。全部点灯でクリア。','同じ灯りを2回押すと効果は打ち消し合います。押す位置を記録し、最短解から余計に押す回数を減らす。','採点は100 − (実際の手数−最短手数)×3 − ヒント回数×8。Sは95以上。最短より+1手なら97、+2手なら94です。','下の解法確認へ盤面を入力すると最短の押す位置を確認できます。ゲーム内ヒントを使うとSに届かないので、練習で仕組みを覚えましょう。'],echo:['潮・芽・金・虹の4つの順番を覚え、同じ順番で返します。3節あり、次の節で1音ずつ長くなります。','音が使えなくても色と記号で追えます。最初の提示を丁寧に覚え、区切って記憶する。','採点は100 − 間違い×12 − 聴き直し×6。Sは間違い・聴き直しゼロが必要。最初の提示は減点されません。','焦ったら練習や一音ずつの確認で順序を覚える。本番の聴き直しを重ねるとクリアできても評価が下がります。'],crystal:['5×5の盤面で隣接する結晶を入れ替え、同じ色を縦横3つ以上そろえます。そろわない入替は手数を消費しません。','4つ以上の並びで星結晶が生まれ、爆発の起点になります。複数の消去が続く連鎖は、消えた数×連鎖数で彩りを伸ばす。','風力ではなく連鎖のゲージを12までためるとフィーバー。得点が2倍。1回だけの虹の一閃は選んだ横一列を消し、手数を消費しません。','採点は50 + 残り手数×2 + 最大連鎖（上限5）×7 + 作った星結晶（上限3）×3。目標の彩りへ到達した上で95以上がS。残り手数・連鎖・星結晶をバランス良く伸ばす。']};
function renderMini(){const id=selectedMini,g=D.mini[id];$('#miniTabs').innerHTML=Object.entries(D.mini).map(([id,g])=>`<button data-mini="${id}" aria-pressed="${id===selectedMini}">${g.title}</button>`).join('');const rule=t=>id==='voyage'?`${D.voyageRules[t].length}歩・船体${D.voyageRules[t].hp}・目標${D.voyageRules[t].target}`:id==='crystal'?`${D.crystalRules[t].moves}手・目標彩り${D.crystalRules[t].target}`:id==='lantern'?g.sizes[t].join('×'):`${g.lengths[t]} → ${g.lengths[t]+1} → ${g.lengths[t]+2}音`;$('#miniDetail').innerHTML=`<img src="media/${id}.webp" alt="${g.title}のゲーム素材" loading="lazy"><div><p class="eyebrow">${D.chapters.find(c=>c.key===g.need)?.act}解放 / ${g.label}</p><h3>${g.title}</h3><p>${esc(g.desc)}</p><ol>${miniTips[id].map(t=>`<li>${esc(t)}</li>`).join('')}</ol></div><div class="table-wrap" style="grid-column:1/-1"><table><caption>難易度と評価報酬（しずくの累計上限）</caption><thead><tr><th>難易度</th><th>ルール</th><th>C / B / A / S</th><th>Sまでの評価素材</th></tr></thead><tbody>${Object.keys(names).map((t,i)=>{const bag={};g.tiers[t].forEach(r=>Object.entries(r.materials).forEach(([id,n])=>bag[id]=(bag[id]||0)+n));return `<tr><td>${names[t]}</td><td>${rule(t)}</td><td>${[[20,35,50,70],[30,50,75,100],[40,70,100,140]][i].join(' / ')}</td><td>${loot(bag)}</td></tr>`;}).join('')}</tbody></table></div><p class="small-note" style="grid-column:1/-1">評価は95以上S / 80以上A / 60以上B / それ以下C。表の素材はC〜Sの評価分の累計。ハード初回の核2つは別枠です。</p>`;}
const chapterNotes={prologue:'雨の港で育ったアリアは、人の心を色と音で感じます。リラから「聞こえた色は、その人の答えじゃない」と学び、心ではなく貼りついた穢れを切る心剣に出会います。波の夜の喪失から、小さなノアールと旅が始まります。',act1:'アクアミストの鐘楼で、マリーの帰りを待つグランに出会います。通常戦で階段を開き、汚染された鯨の穢れを3段階でほどくと、グランが仲間になります。',act2:'灰色の街で青年・馨と出会い、答えを言い当てず、そばに置く三日間を過ごします。選択肢は相手の時間を待つ行動で進みます。テラ・コッタに戦闘はありません（最終章を除く）。世界じゅうを旅したマリーも、この街の話はしなかった。',act3:'茨の森のアイビーは、姉との比較の声に縛られています。森の通常戦からボス戦へ進み、本人の色を消さずに声をほどく。第三幕は森と赤い丘へ、どちらからでも進めます。アイビーとヴァルドの両方が加入してから第四幕へ。マリーとの昔の交流が、葉の目印と丘の果実をつなぎます。',act4:'グラン・アイビー・ヴァルドと黄金の渓谷へ。傷を隠そうと鉛のドームへ閉じこもったスピネルと向き合います。傷の線を消さずに金でつなぎ、守りを取り戻した精霊が加入します。',act5:'グラン・アイビー・ヴァルド・スピネルがそろってから、パレット王に貼りついた漆黒の命令を切り分けます。七色の調和とアリアの出自、光の国クリスタリアへの道が見えてきます。旅の各地に貼られていた「世界を黒で揃えろ」という布告は王の印でしたが、王の心ではありませんでした。色の国々の物語はここで終わり、パレット王は仲間にならずに宝具「双彩の王笏」（1ターンに2体まで召喚）を託します。ここではまだ本編クリアではありません。',finale:'夜渡りのネフラを解放してクロムへ。黒そのものを消さず、黒へ貼りついた白い膜を切る戦いです。ノアールの小さな夜空が戦場の道を取り戻します。夜空に戻る精霊はグラン→アイビー→スピネル→ヴァルド。結末で、ノアは自分の生まれと名前を思い出します。',epilogue:'クロム撃破後のエピローグを最後まで読むとクリア記録となり、復興の旅が開きます。失った人を取り戻す話ではなく、残った人の明日を修理する続きへ。復興編を読み終えると、テラ・コッタから最終章「灰色の継ぎ目」が開きます。'};
function chapterStages(key){if(key.startsWith('restore')){const p=D.guardians.find(p=>p.chapter===key);return[...(p?[p.pathId,p.bossId]:[]),...(key==='restore4'?['gp_cocoon','mr_cocoon']:[]),key].filter(id=>D.stages.some(s=>s.id===id));}return D.stages.filter(s=>s.group==='main'&&(s.gate===key||storyForStage(s)===key)).sort((a,b)=>a.id.startsWith('gp_')?-1:b.id.startsWith('gp_')?1:0).map(s=>s.id);}
function renderStory(){$('#storyTimeline').innerHTML=D.chapters.filter(c=>Object.hasOwn(chapterNotes,c.key)).map(c=>`<article class="chapter-card"><p class="eyebrow">${c.act}</p><h3>${c.title}</h3><p>${chapterNotes[c.key]}</p><a class="text-link" href="story.html#${c.key}">章の本文・全会話を読む →</a><div class="route-sequence">${chapterStages(c.key).map(id=>`<button class="text-link" data-open-stage="${id}">${esc(D.stages.find(s=>s.id===id).title)} →</button>`).join('')}</div></article>`).join('')+`<article class="chapter-card"><p class="eyebrow">紅角の丘 / 第三幕以降</p><h3>怒りの向け先</h3><p>折れ枝の道→ヴァルド戦→加入会話。盗まれた生命の実のせいで妻ルベラと生まれるはずだった子を失った紅い竜。怒りは本人のもので、アリアは「怒っていいよ」から向き合います。浄化しても怒りは消えず、生きるための火に変わります。マリーとの過去が語られ、戦闘の直後にグランと意気投合し「潮の友」となります。</p><a class="text-link" href="story.html#fury">丘の物語・精霊との掛け合いを読む →</a></article>`;$('#postTimeline').innerHTML=D.restorationChapters.map((c,i)=>`<article class="post-chapter"><p class="eyebrow">${c.act} · ふつう適正Lv${c.lv}</p><h4>${c.title}</h4><p>${c.goal} ${c.note}</p><a class="text-link" href="story.html#${c.key}">章の本文を読む</a><div>${chapterStages(c.key).map(id=>`<button class="text-link" data-open-stage="${id}">${esc(D.stages.find(s=>s.id===id).title)}</button>`).join('')}</div></article>`).join('')+[['restored','復興編 エピローグ','今日の色で、ただいま','なくした人は戻らない。けれど、今いる人の窓に灯が戻る。リラの席を残したまま、二人と一振りは明日の修理へ。'],['seam','最終章 · 適正Lv34','灰色の継ぎ目','クロムと馨はカフェで初めて出会う。馨は向こう側（現実の世界）から十六年前に落ちてきた人だった。溢れた闇が馨に降り注ぎ、この世界を包もうとする。アリアとクロムは闇だけを切り分け、馨の頼みで、混ざりこんだ二つの世界を分ける。']].map(([key,act,title,text])=>`<article class="post-chapter"><p class="eyebrow">${act}</p><h4>${title}</h4><p>${text}</p><a class="text-link" href="story.html#${key}">章の本文を読む</a><div>${key==='seam'&&D.stages.some(s=>s.id==='seam')?'<button class="text-link" data-open-stage="seam">灰色の継ぎ目（馨戦）</button>':''}</div></article>`).join('');}
function renderChecklist(){const entries=Object.entries(notes).filter(([id,v])=>v===true&&D.stages.some(s=>s.id===id.split('@')[0])&&Object.hasOwn(names,id.split('@')[1]));$('#checklistCount').textContent=`攻略メモ ${entries.length}件 / 難易度を含む${D.stages.filter(s=>!s.hardOnly).length*3+D.stages.filter(s=>s.hardOnly).length}戦場（${D.stages.filter(s=>!s.hardOnly).length}×3 + ハード専用${D.stages.filter(s=>s.hardOnly).length}）`;$('#checklistItems').innerHTML=entries.filter(([id])=>visibleStage(D.stages.find(s=>s.id===id.split('@')[0]))).map(([id])=>{const [stage,tier]=id.split('@');return `<button data-note-stage="${stage}" data-note-tier="${tier}">${esc(D.stages.find(s=>s.id===stage).title)} · ${names[tier]} ✓</button>`;}).join('')||'<span class="small-note">まだ攻略メモがありません。</span>';}
function globalMatches(q){const a=D.stages.filter(visibleStage).map(s=>({type:'stage',id:s.id,label:s.title,hay:s.title+s.id+s.act+s.description+D.spirits[s.guardian]?.name+(s.guardian||'')})).concat(D.skills.filter(s=>true).map(s=>({type:'skill',id:s.id,label:s.name,hay:s.name+s.desc+D.spirits[s.spirit].name})),D.gear.filter(g=>post()||!g.legendary).map(g=>({type:'gear',id:g.id,label:g.name,hay:g.name+g.desc})),D.items.map(g=>({type:'gear',id:g.id,label:g.name,hay:g.name+g.desc})),Object.entries(D.materials).map(([id,m])=>({type:'gear',id,label:m.name,hay:m.name+m.desc+m.source})),Object.entries(D.mini).map(([id,g])=>({type:'mini',id,label:g.title,hay:g.title+g.desc})));return a.filter(x=>x.hay.includes(q));}
function renderSearch(){const q=$('#globalSearch').value.trim(),out=$('#searchResults');out.hidden=!q;if(!q)return;const r=globalMatches(q);out.innerHTML=`<p>${r.length}件${r.length>30?' / 先頭30件を表示':''}${post()?'':' · 復興編は非表示'}</p>`+r.slice(0,30).map(r=>`<button data-search-type="${r.type}" data-search-id="${r.id}"><small>${{stage:'ステージ',skill:'スキル',gear:'装備・素材',mini:'ミニゲーム'}[r.type]}</small><span>${esc(r.label)}</span><span aria-hidden="true">→</span></button>`).join('')+(r.length?'':empty('該当なし。短い名前や、復興編の表示を試してください。'));}
function openGear(id){$('#gearKind').value='all';$('#gearSlot').value='all';$('#gearSearch').value=itemName(id);renderGear();$('#equipment').scrollIntoView({behavior:motion()});}
function openSkill(id){const s=D.skills.find(s=>s.id===id);selectedSpirit=s.spirit;$('#skillRoute').value=s.route;$('#skillSearch').value=s.name;renderSpirits();$('#skills').scrollIntoView({behavior:motion()});}
let lampRows=3,lampCols=3,lampState=0;
function lampMask(r,c,i){let mask=0,rr=Math.floor(i/c),cc=i%c;for(const[a,b]of[[0,0],[-1,0],[1,0],[0,-1],[0,1]])if(rr+a>=0&&rr+a<r&&cc+b>=0&&cc+b<c)mask|=1<<((rr+a)*c+cc+b);return mask;}
function bitCount(n){let x=0;for(;n;n&=n-1)x++;return x;}
function solveLamp(r,c,board){const n=r*c,full=(1<<n)-1;let best=null,bc=Infinity;for(let presses=0;presses<=full;presses++){const num=bitCount(presses);if(num>=bc)continue;let b=board;for(let j=0;j<n;j++)if(presses&(1<<j))b^=lampMask(r,c,j);if(b===full){best=presses;bc=num;}}return best;}
function renderLamp(solution=null){$('#lampBoard').style.gridTemplateColumns=`repeat(${lampCols},1fr)`;$('#lampBoard').innerHTML=Array.from({length:lampRows*lampCols},(_,i)=>`<button data-lamp="${i}" aria-pressed="${!!(lampState&(1<<i))}" class="${solution!==null&&(solution&(1<<i))?'solution':''}" aria-label="${Math.floor(i/lampCols)+1}行${i%lampCols+1}列 ${lampState&(1<<i)?'点灯':'消灯'}">${lampState&(1<<i)?'✦':'·'}</button>`).join('');}
function installMCP(){const context=document.modelContext;if(!context?.registerTool)return;const life=new AbortController();const tools=[{name:'get_stage_guide',title:'ステージ攻略を調べる',description:'この攻略帳に収録されたステージの難易度別編成・S条件・報酬を返す。復興編は画面のネタバレ設定に従う。',inputSchema:{type:'object',properties:{stageId:{type:'string'},difficulty:{type:'string',enum:['gentle','normal','hard']}},required:['stageId','difficulty'],additionalProperties:false},execute(input){if(!input||Object.keys(input).some(k=>!['stageId','difficulty'].includes(k))||typeof input.stageId!=='string'||!Object.hasOwn(names,input.difficulty))throw Error('有効なstageIdとdifficultyが必要です。');const s=D.stages.find(s=>s.id===input.stageId&&visibleStage(s));if(!s||!s.tiers[input.difficulty])throw Error('ステージが未表示、または対応する難易度がありません。');return{stage:s.title,id:s.id,difficulty:names[input.difficulty],...s.tiers[input.difficulty],missions:s.missions.map(m=>({condition:mission(m,s),strategy:hint(m)})),guide:s.missionGuide};}},{name:'search_strategy_guide',title:'攻略帳を検索',description:'表示中のネタバレ設定に従ってステージ・スキル・装備・素材・ミニゲームを検索する。',inputSchema:{type:'object',properties:{query:{type:'string',minLength:1,maxLength:80}},required:['query'],additionalProperties:false},execute(input){if(!input||Object.keys(input).some(k=>k!=='query')||typeof input.query!=='string'||!input.query.trim()||input.query.length>80)throw Error('1〜80文字の検索語が必要です。');return{matches:globalMatches(input.query.trim()).map(({type,id,label})=>({type,id,label})).slice(0,50)};}}];for(const t of tools){try{Promise.resolve(context.registerTool({...t,annotations:{readOnlyHint:true,untrustedContentHint:false}},{signal:life.signal})).catch(()=>{});}catch{}}addEventListener('pagehide',()=>life.abort(),{once:true});}
const traitText={reach:'槍の間合い（射程1〜2）',fog:'射程4・立っているあいだ霧が濃い（視界−1）',guard:'大盾（守りが硬い）',might:'剛力（攻撃が重い）',lead:'近衛の長（射程1〜2）',raid:'本陣を狙う騎兵',root:'当てた相手を蔓で縛る'};
function renderCamps(){const el=$('#campBattles');if(!el||!D.campBattles)return;el.innerHTML=D.campBattles.map(b=>`<article class="camp-card"><p class="eyebrow">${esc(b.act)} · 推奨Lv${b.lv} · ${b.size[0]}×${b.size[1]}</p><h4><button class="text-link" data-guide-stage="${esc(b.id)}">${esc(b.title)}</button></h4><p>${esc(b.desc)}</p><p class="small-note">中立の旗${b.flags.neutral} · 敵の旗${b.flags.enemy} · 土嚢${b.sandbags} · 指揮点 最大${b.cpMax}</p><ul class="guard-list">${b.guards.map(g=>`<li style="--guard:${esc(g.color)}"><b>${esc(g.name)}</b><span>${esc(g.post)} · ${esc(traitText[g.trait]||g.trait)}</span><q>${esc(g.sight)}</q></li>`).join('')}</ul></article>`).join('');el.querySelectorAll('[data-guide-stage]').forEach(x=>x.onclick=()=>{selectedStage=x.dataset.guideStage;$('#stageGroup').value='all';renderStages();location.hash='stages';});}
function setup(){renderCamps();const initialStage=new URLSearchParams(location.search).get("stage");if(D.stages.some(s=>s.id===initialStage)){selectedStage=initialStage;if(D.stages.find(s=>s.id===initialStage).postgame)$("#showPostgame").checked=true;}for(const s of ['#stageSearch','#stageGroup','#stageType','#stageDifficulty'])$(s).addEventListener(s==='#stageSearch'?'input':'change',renderStages);$('#showPostgame').onchange=()=>{renderStages();renderSpirits();renderGear();renderSearch();renderChecklist();renderPlanner();};for(const s of ['#skillRoute','#skillLevel','#skillSearch'])$(s).addEventListener(s==='#skillSearch'?'input':'change',renderSkills);for(const s of ['#gearSearch','#gearKind','#gearSlot'])$(s).addEventListener(s==='#gearSearch'?'input':'change',renderGear);$('#planSpirit').innerHTML=Object.entries(D.spirits).map(([id,s])=>`<option value="${id}">${s.name}</option>`).join('');for(const s of ['#planSpirit','#planFrom','#planTo','#planCount'])$(s).addEventListener(s==='#planCount'?'input':'change',renderPlanner);$('#globalSearch').oninput=renderSearch;$('#clearSearch').onclick=()=>{$('#globalSearch').value='';renderSearch();$('#globalSearch').focus();};$('#revealAll').onclick=()=>{$('#showPostgame').checked=true;renderStages();renderSpirits();renderGear();$('#stages').scrollIntoView({behavior:motion()});};$('#legendIndex').onclick=()=>{$('#showPostgame').checked=true;$('#stageGroup').value='legend';$('#stageType').value='all';$('#stageSearch').value='';$('#stageDifficulty').value='hard';renderStages();$('#stages').scrollIntoView({behavior:motion()});};$('#lampSize').onchange=()=>{[lampRows,lampCols]=$('#lampSize').value.split(',').map(Number);lampState=0;renderLamp();$('#lampResult').textContent='点灯状態を入力してください。';};$('#lampSolve').onclick=()=>{const s=solveLamp(lampRows,lampCols,lampState);renderLamp(s);$('#lampResult').textContent=s===null?'この盤面は全点灯にできません。ゲームの点灯状態を確認してください。':s===0?'すべて点灯しています。0手で完成。':`最短${bitCount(s)}手。水色の枠の位置を各1回押すと全点灯。順番は自由です。`;};$('#lampReset').onclick=()=>{lampState=0;renderLamp();$('#lampResult').textContent='すべて消灯しました。';};$('#resetChecklist').onclick=()=>{notes={};try{localStorage.removeItem('cr-guide-checklist-v1');}catch{}renderChecklist();renderStage();};document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.stage){selectedStage=b.dataset.stage;renderStages();if(innerWidth<=800)$('#stageDetail').scrollIntoView({behavior:motion()});}if(b.dataset.openStage)openStage(b.dataset.openStage);if(b.dataset.spirit){selectedSpirit=b.dataset.spirit;$('#skillSearch').value='';renderSpirits();}if(b.dataset.loot)openGear(b.dataset.loot);if(b.dataset.compare){if(compared.includes(b.dataset.compare))compared=compared.filter(id=>id!==b.dataset.compare);else{if(compared.length===2)compared.shift();compared.push(b.dataset.compare);}renderGear();$('#compareBox').scrollIntoView({behavior:motion(),block:'center'});}if(b.dataset.mini){selectedMini=b.dataset.mini;renderMini();}if(b.dataset.lamp!==undefined){lampState^=1<<+b.dataset.lamp;renderLamp();$('#lampResult').textContent='点灯状態を入力中。最短解を調べると押す位置を表示します。';}if(b.dataset.noteStage){$('#stageDifficulty').value=b.dataset.noteTier;openStage(b.dataset.noteStage);}if(b.dataset.searchType){if(b.dataset.searchType==='stage')openStage(b.dataset.searchId);if(b.dataset.searchType==='skill')openSkill(b.dataset.searchId);if(b.dataset.searchType==='gear')openGear(b.dataset.searchId);if(b.dataset.searchType==='mini'){selectedMini=b.dataset.searchId;renderMini();$('#minigames').scrollIntoView({behavior:motion()});}}});$('#shopList').innerHTML=Object.entries(D.shops).map(([id,v])=>`<h3>${shops[id]}</h3><p>${v.map(itemName).join('・')}</p><p>強化素材：${(D.materialShops[id]||[]).map(itemName).join('・')||'販売なし'}</p>`).join('');$('#growthTable').innerHTML=`<table class="growthTable"><caption>Lv成長値（例：HP 60 + 10×Lv）</caption><thead><tr><th>キャラ</th><th>HP</th><th>攻撃</th><th>守り</th><th>移動 / 射程</th></tr></thead><tbody>${Object.entries(D.grow).map(([id,g])=>`<tr><td>${D.kindNames[id]||D.spirits[id]?.name||id}</td><td>${g.hp[0]} + ${g.hp[1]}×Lv</td><td>${g.atk[0]} + ${g.atk[1]}×Lv</td><td>${g.def[0]} + ${g.def[1]}×Lv</td><td>${g.mov} / ${g.rng.join('〜')}</td></tr>`).join('')}</tbody></table>`;renderStages();renderSpirits();renderPlanner();renderGear();renderMini();renderStory();renderChecklist();renderLamp();installMCP();$('#loadStatus').textContent=`全${D.stages.length}ステージ・${D.skills.length}スキル・${D.gear.length}装備を読み込みました。`;}
const menu=$('.menu-button');menu.onclick=()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));$('#navigation').classList.toggle('open',open);};$('#navigation').querySelectorAll('a').forEach(a=>a.onclick=()=>{menu.setAttribute('aria-expanded','false');$('#navigation').classList.remove('open');});const dialog=$('#screenDialog');document.querySelectorAll('[data-screen]').forEach(b=>b.onclick=()=>{const f=b.dataset.screen==='forge';$('#dialogImage').src=`media/${f?'forge':'battle'}.png`;$('#dialogImage').alt=f?'マリー加入後のスキル強化画面':'ヴァルドの戦闘画面';$('#dialogCaption').textContent=f?'スキル強化の実際の画面（復興編の仲間を含む）':'虹の床と突進の予告線';dialog.showModal();});$('.dialog-close').onclick=()=>dialog.close();dialog.onclick=e=>{if(e.target===dialog)dialog.close();};document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menu.getAttribute('aria-expanded')==='true'){menu.setAttribute('aria-expanded','false');$('#navigation').classList.remove('open');menu.focus();}});fetch('data.json?v=20261021a').then(r=>{if(!r.ok)throw Error('data');return r.json();}).then(d=>{D=d;setup();}).catch(()=>{$('#loadStatus').textContent='攻略データを読み込めませんでした。再読み込みしてください。';$('#stageDetail').innerHTML=empty('読み込みに失敗しました。再読み込みしてください。');});
